// BFS over Sokoban states. State key = player index + sorted box indices.
const LEVELS = {
  '1': [
    '#######',
    '##  .##',
    '##   ##',
    '#* @  #',
    '#  $  #',
    '##  ###',
    '#######',
  ],
  '2': [
    '#######',
    '##    #',
    '## #@ #',
    '## $* #',
    '## .* #',
    '##    #',
    '#######',
  ],
};

const pick = String(nb.get('sokoban_level') || '1');
const rows = LEVELS[pick];
const W = rows[0].length, H = rows.length;

const walls = [], goals = [];
let player = -1;
const boxes = [];
rows.forEach((row, y) => {
  [...row].forEach((ch, x) => {
    const i = y * W + x;
    if (ch === '#') walls.push(i);
    if (ch === '.' || ch === '*') goals.push(i);
    if (ch === '$' || ch === '*') boxes.push(i);
    if (ch === '@') player = i;
  });
});
const wallSet = new Set(walls);
const goalSet = new Set(goals);

const keyOf = (p, bs) => p + '|' + [...bs].sort((a, b) => a - b).join(',');
const solvedCheck = bs => [...bs].every(b => goalSet.has(b));

const DIRS = { U: -W, D: W, L: -1, R: 1 };
const start = { p: player, bs: new Set(boxes) };
const seen = new Set([keyOf(start.p, start.bs)]);
const queue = [{ ...start, moves: '' }];
let solution = null, explored = 0;

while (queue.length) {
  const cur = queue.shift();
  explored++;
  if (solvedCheck(cur.bs)) { solution = cur.moves; break; }
  for (const [name, d] of Object.entries(DIRS)) {
    const next = cur.p + d;
    if (wallSet.has(next)) continue;
    let bs = cur.bs;
    if (bs.has(next)) {
      const pushed = next + d;
      if (wallSet.has(pushed) || bs.has(pushed)) continue;  // blocked push
      bs = new Set(bs);
      bs.delete(next);
      bs.add(pushed);
    }
    const key = keyOf(next, bs);
    if (seen.has(key)) continue;
    seen.add(key);
    queue.push({ p: next, bs, moves: cur.moves + name });
  }
}

if (!solution) return 'BFS exhausted ' + explored + ' states: level ' + pick + ' is unsolvable!';
console.log('level ' + pick + ': solved in ' + solution.length + ' moves after exploring ' +
  explored + ' of ' + seen.size + ' discovered states');
console.log('optimal moves:', solution);

nb.set('sokoban', { rows, solution, level: pick });
return { level: pick, optimalMoves: solution.length, statesExplored: explored };
